import manifest from "./manifest.generated.json";
import type { MangaChapter, MangaEdition, MangaVolume, ReadingAsset } from "../catalog";
import type { MangaSnapshot } from "../types";

/**
 * KAZE Originals — demonstration series written and illustrated for this project
 * (artwork generated by scripts/manga-demo/generate.mjs). They exist so the reader works end-to-end
 * without any commercial licence. They are always labelled as demo content in the UI.
 */

export type DemoSeries = {
  /** Negative ids never collide with AniList ids (always positive). */
  id: number;
  slug: string;
  title: string;
  titleNative: string;
  author: string;
  description: string;
  genres: string[];
  format: "MANGA";
  country: "JP" | "KR";
  status: "RELEASING" | "FINISHED";
  readingDirection: "rtl" | "ltr" | "vertical";
  color: string;
  cover: string;
  banner: string | null;
  year: number;
  edition: MangaEdition;
  volumes: MangaVolume[];
  chapters: (MangaChapter & { pages: ReadingAsset[] })[];
};

type ManifestPage = { src: string; alt: string; width: number; height: number; spread: boolean };
const m = manifest as unknown as { series: Record<string, { cover: string; chapters: Record<string, ManifestPage[]> }> };

function assets(list: ManifestPage[]): ReadingAsset[] {
  return list.map((p, index) => ({ index, src: p.src, srcLow: null, width: p.width, height: p.height, alt: p.alt, spread: p.spread }));
}

