export const DEMO_LICENSE = (manifest as { license: string }).license;

export function demoBySlug(slug: string) {
  return DEMO_SERIES.find((s) => s.slug === slug) ?? null;
}

export function demoById(id: number) {
  return DEMO_SERIES.find((s) => s.id === id) ?? null;
}

export function demoByKey(key: string) {
  return DEMO_SERIES.find((s) => s.edition.seriesKey === key) ?? null;
}

export function demoChapter(chapterId: string) {
  for (const s of DEMO_SERIES) {
    const c = s.chapters.find((ch) => ch.id === chapterId);
    if (c) return { series: s, chapter: c };
  }
  return null;
}

export function demoSnapshot(s: DemoSeries): MangaSnapshot {
  return {
    kind: "manga",
    title: s.title,
    titleNative: s.titleNative,
    cover: s.cover,
    banner: s.banner,
    color: s.color,
    chapters: null,
    volumes: null,
    format: s.format,
    country: s.country,
    year: s.year,
    genres: s.genres,
    averageScore: null,
    author: s.author,
    slug: s.slug,
  };
}
